import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

gelu_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cstdint>

__device__ __forceinline__ float fast_tanh(float x) {
    // Fast tanh approximation using the __expf intrinsic.
    // tanh(x) = sign(x) * (1 - e^{-2|x|}) / (1 + e^{-2|x|})
    float e = __expf(-2.0f * fabsf(x));
    float t = __fdividef(1.0f - e, 1.0f + e);
    return copysignf(t, x);
}
__device__ __forceinline__ float4 gelu_float4(float4 v) {
    const float c = 0.7978845608028654f; // sqrt(2/pi)
    const float a = 0.044715f;
    float x0 = v.x, x1 = v.y, x2 = v.z, x3 = v.w;
    float t0 = c * fmaf(a * x0 * x0, x0, x0);
    float t1 = c * fmaf(a * x1 * x1, x1, x1);
    float t2 = c * fmaf(a * x2 * x2, x2, x2);
    float t3 = c * fmaf(a * x3 * x3, x3, x3);
    float o0 = 0.5f * x0 * (1.0f + fast_tanh(t0));
    float o1 = 0.5f * x1 * (1.0f + fast_tanh(t1));
    float o2 = 0.5f * x2 * (1.0f + fast_tanh(t2));
    float o3 = 0.5f * x3 * (1.0f + fast_tanh(t3));
    return make_float4(o0, o1, o2, o3);
}
__global__ void gelu_kernel_vec4(const float4* __restrict__ x, float4* __restrict__ y, int n4) {
    int stride = blockDim.x * gridDim.x;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    // Process two float4 elements per iteration to increase instruction-level
    // parallelism and reduce loop-control overhead for large tensors.
    for (; idx + stride < n4; idx += stride * 2) {
        float4 v0 = __ldg(&x[idx]);
        float4 v1 = __ldg(&x[idx + stride]);
        y[idx] = gelu_float4(v0);
        y[idx + stride] = gelu_float4(v1);
    }
    if (idx < n4) {
        float4 v = __ldg(&x[idx]);
        y[idx] = gelu_float4(v);
    }
}
__global__ void gelu_kernel_scalar(const float* __restrict__ x, float* __restrict__ y, int n) {
    const float c = 0.7978845608028654f;
    const float a = 0.044715f;
    int stride = blockDim.x * gridDim.x;
    for (int idx = blockIdx.x * blockDim.x + threadIdx.x; idx < n; idx += stride) {
        float xv = __ldg(&x[idx]);
        float t = c * fmaf(a * xv * xv, xv, xv);
        y[idx] = 0.5f * xv * (1.0f + fast_tanh(t));
    }
}
torch::Tensor gelu_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "input must be float32");
    auto x_contig = x.contiguous();
    auto y = torch::empty_like(x_contig);
    int n = x_contig.numel();
    const int threads = 256;
    bool aligned16 =
        (reinterpret_cast<uintptr_t>(x_contig.data_ptr<float>()) % 16 == 0) &&
        (reinterpret_cast<uintptr_t>(y.data_ptr<float>()) % 16 == 0);
    if (n % 4 == 0 && aligned16) {
        int n4 = n / 4;
        int max_blocks = (n4 + threads - 1) / threads;
        int blocks = max_blocks;
        if (blocks < 1) blocks = 1;
        gelu_kernel_vec4<<<blocks, threads>>>(
            reinterpret_cast<const float4*>(x_contig.data_ptr<float>()),
            reinterpret_cast<float4*>(y.data_ptr<float>()),
            n4
        );
    } else {
        int max_blocks = (n + threads - 1) / threads;
        int blocks = max_blocks;
        if (blocks < 1) blocks = 1;
        gelu_kernel_scalar<<<blocks, threads>>>(
            x_contig.data_ptr<float>(),
            y.data_ptr<float>(),
            n
        );
    }
    return y;
}
"""
gelu_cpp_source = "torch::Tensor gelu_cuda(torch::Tensor x);"
gelu_module = load_inline(
    name="gelu_module",
    cpp_sources=gelu_cpp_source,
    cuda_sources=gelu_source,
    functions=["gelu_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.gelu_cuda = gelu_module.gelu_cuda

    def forward(self, x):
        return self.gelu_cuda(x.cuda())

